package com.futahua.papers.mobile;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
/** Own fixture only; checks read amplification and durable resource lookup. */
public final class PhoneCatalogCheck extends Instrumentation {
 private JSONObject get(String route,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:48240"+route).openConnection();c.setRequestProperty("Authorization","Bearer "+token);c.setConnectTimeout(5000);c.setReadTimeout(15000);try{if(c.getResponseCode()!=200)throw new IOException("Owner refused read");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 @Override public void onCreate(Bundle args){start();}
 @Override public void onStart(){Bundle result=new Bundle();PhonePeerServer peer=null,reopened=null;File fixture=new File(Environment.getExternalStorageDirectory(),"Download/PapersCatalogCheck-"+UUID.randomUUID());try{
 peer=new PhonePeerServer(getTargetContext());peer.start();JSONObject grant=MobileFiles.get(getTargetContext()).peerInvitations(peer.owner).getJSONObject(0);String token=grant.getString("token"),id=get("/v1/files/shares",token).getJSONArray("entries").getJSONObject(0).getString("id");Thread.sleep(1200);long before=peer.resourceCatalogWrites(),start=System.nanoTime();for(int i=0;i<12;i++)get("/v1/files/"+id+"/stat",token);Thread.sleep(700);if(peer.resourceCatalogWrites()!=before)throw new IOException("Unchanged reads rewrote resource catalog");result.putLong("twelveReadsMs",(System.nanoTime()-start)/1000000);result.putBoolean("unchangedReadsDoNotWrite",true);
 if(!fixture.mkdir())throw new IOException("Own fixture creation failed");java.lang.reflect.Method entry=PhonePeerServer.class.getDeclaredMethod("entry",File.class,JSONObject.class);entry.setAccessible(true);String fixtureId=((JSONObject)entry.invoke(peer,fixture,grant)).getString("id");peer.close();peer=null;
 reopened=new PhonePeerServer(getTargetContext());java.lang.reflect.Method resolve=PhonePeerServer.class.getDeclaredMethod("resolve",String.class,JSONObject.class);resolve.setAccessible(true);if(!((File)resolve.invoke(reopened,fixtureId,grant)).getCanonicalFile().equals(fixture.getCanonicalFile()))throw new IOException("Close lost resource mapping");result.putBoolean("newMappingSurvivesRestart",true);finish(Activity.RESULT_OK,result);
 }catch(Exception e){result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{if(peer!=null)try{peer.close();}catch(Exception ignored){}if(reopened!=null)try{reopened.close();}catch(Exception ignored){}if(fixture.getName().startsWith("PapersCatalogCheck-")&&fixture.getParentFile().getName().equals("Download"))fixture.delete();}}
}
